import{_ as d,a0 as s,w as p,s as l,ao as u,I as r,x as t,a1 as i,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"Intel 展示了可在大屏幕显示 Linux 系统的低端 Android 手机 | LCTT x X-CMD","titleTemplate":false,"description":"Intel 展示了可在大屏幕显示 Linux 系统的低端 Android 手机 | LCTT (201605) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Intel 展示了可在大屏幕显示 Linux 系统的低端 Android 手机 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Intel 展示了可在大屏幕显示 Linux 系统的低端 Android 手机 | LCTT (201605) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201605/20160223 Intel shows budget Android phone powering big-screen Linux","title":"Intel 展示了可在大屏幕显示 Linux 系统的低端 Android 手机","tag":"201605","desc":""},"relativePath":"201605/20160223 Intel shows budget Android phone powering big-screen Linux.md","filePath":"[post].md"}'),a={name:"201605/20160223 Intel shows budget Android phone powering big-screen Linux.md"};function m(x,n,g,_,L,w){const e=s("Link");return p(),l("div",null,[n[13]||(n[13]=u('<h1 id="intel-展示了可在大屏幕显示-linux-系统的低端-android-手机" tabindex="-1">Intel 展示了可在大屏幕显示 Linux 系统的低端 Android 手机 <a class="header-anchor" href="#intel-展示了可在大屏幕显示-linux-系统的低端-android-手机" aria-label="Permalink to “Intel 展示了可在大屏幕显示 Linux 系统的低端 Android 手机”">​</a></h1><p><img src="https://regmedia.co.uk/2016/02/23/intel-bigscreen.jpg?x=648&amp;y=348&amp;crop=1" alt=""></p><p>在世界移动大会 <strong>MWC16</strong> 上 Intel 展示了称之为“大屏体验”的一款的 Android 智能手机，它在插入一个外部显示后运行了一个完整的 Linux 桌面。</p><p>这个概念大体上与微软在 Windows 10 手机中的 Continuum 相似，但是 Continuum 面向的是高端设备，Intel 的项目面向的是低端智能机和新兴市场。</p><p>在巴塞罗那的这场大会上展示的是拥有 Atom x3、2GB RAM 和 16GB 存储以及支持外部显示的的 SoFIA（Intel 架构的智能或功能手机）智能机原型。插上键盘、鼠标和显示，它就变成了一台桌面 Linux，并可以选择在大屏幕的一个窗口中显示 Android 桌面。</p><p>Intel 的拓荒小组（Path Finding Group）经理 Nir Metzer 告诉我们：“Android 基于 Linux 内核，因此我们运行在一个内核上，我们有一个 Android 栈和一个 Linux 栈，并且我们共享同一个环境，因此文件系统是相同的。电话是全功能的。”</p><p>Metzer 说：“我有一个多窗口环境。只要我插入显示器后就可以使用电子表格，我可以进行拖放操作，播放音频。在一个低端平台实现这一切是一个挑战。”</p><p>现在当连上外部显示器时设备的屏幕显示是空白的，但是 Metzer 说下个版本的 Atom X3 会支持双显示。</p><p>其使用的 Linux 版本是由 Intel 维护的。Metzer 说：“我们需要将 Linux 和 Android 保持一致。框架是预安装的，你不能下载任何 app。”</p><p>英特尔在移动世界大会上向手机制造商们推销这一想法，但却没有实际说希望购买该设备的消费者。Metzer 说：“芯片已经准备好了，已经为量产准备好了。明天就可以进入生产。但是这要看商业需求。”</p><hr>',11)),r("p",null,[n[1]||(n[1]=t("via: ",-1)),i(e,{href:"http://www.theregister.co.uk/2016/02/23/move_over_continuum_intel_shows_android_smartphone_powering_bigscreen_linux/"},{default:o(()=>[...n[0]||(n[0]=[t("http://www.theregister.co.uk/2016/02/23/move_over_continuum_intel_shows_android_smartphone_powering_bigscreen_linux/",-1)])]),_:1})]),r("p",null,[n[5]||(n[5]=t("作者：",-1)),i(e,{href:"http://www.theregister.co.uk/Author/2878"},{default:o(()=>[...n[2]||(n[2]=[t("Tim Anderson",-1)])]),_:1}),n[6]||(n[6]=t(" 译者：",-1)),i(e,{href:"https://github.com/geekpi"},{default:o(()=>[...n[3]||(n[3]=[t("geekpi",-1)])]),_:1}),n[7]||(n[7]=t(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:o(()=>[...n[4]||(n[4]=[t("wxy",-1)])]),_:1})]),r("p",null,[n[10]||(n[10]=t("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...n[8]||(n[8]=[t("LCTT",-1)])]),_:1}),n[11]||(n[11]=t(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:o(()=>[...n[9]||(n[9]=[t("Linux中国",-1)])]),_:1}),n[12]||(n[12]=t(" 荣誉推出",-1))])])}const I=d(a,[["render",m]]);export{f as __pageData,I as default};
